CREATE TABLE "jules_profiles" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "name" text NOT NULL, "status" text DEFAULT 'active' NOT NULL, "enabled" boolean DEFAULT true NOT NULL, "plan" text, "secret_ref" text NOT NULL, "session_start_limit" integer DEFAULT 15 NOT NULL, "session_start_window_sec" integer DEFAULT 86400 NOT NULL, "concurrent_session_limit" integer DEFAULT 3 NOT NULL, "reserve_session_starts" integer DEFAULT 1 NOT NULL, "capabilities" jsonb DEFAULT '[]'::jsonb NOT NULL, "created_at" timestamp with time zone DEFAULT now() NOT NULL, "updated_at" timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE "company_jules_sources" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "company_id" uuid NOT NULL, "repository" text NOT NULL, "source" text NOT NULL, "starting_branch" text DEFAULT 'main' NOT NULL, "enabled" boolean DEFAULT true NOT NULL, "required_capabilities" jsonb DEFAULT '[]'::jsonb NOT NULL, "created_at" timestamp with time zone DEFAULT now() NOT NULL, "updated_at" timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE "jules_profile_sources" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "profile_id" uuid NOT NULL, "company_source_id" uuid NOT NULL, "status" text DEFAULT 'active' NOT NULL, "verified_at" timestamp with time zone, "created_at" timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE "jules_sessions" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "company_id" uuid NOT NULL, "profile_id" uuid NOT NULL, "company_source_id" uuid NOT NULL, "paperclip_run_id" uuid NOT NULL, "jules_session_id" text NOT NULL, "status" text DEFAULT 'queued' NOT NULL, "outcome_id" text, "last_activity_id" text, "pull_request_url" text, "completion_candidate" boolean DEFAULT false NOT NULL, "result_json" jsonb, "started_at" timestamp with time zone DEFAULT now() NOT NULL, "finished_at" timestamp with time zone, "created_at" timestamp with time zone DEFAULT now() NOT NULL, "updated_at" timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE "jules_capacity_events" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "profile_id" uuid NOT NULL, "company_id" uuid NOT NULL, "session_id" uuid, "event_type" text NOT NULL, "occurred_at" timestamp with time zone DEFAULT now() NOT NULL, "details" jsonb);
CREATE TABLE "jules_callback_events" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "company_id" uuid NOT NULL, "session_id" uuid NOT NULL, "event_id" text NOT NULL, "event_type" text NOT NULL, "payload" jsonb NOT NULL, "created_at" timestamp with time zone DEFAULT now() NOT NULL);
ALTER TABLE "company_jules_sources" ADD CONSTRAINT "company_jules_sources_company_id_companies_id_fk" FOREIGN KEY ("company_id") REFERENCES "companies"("id") ON DELETE cascade;
ALTER TABLE "jules_profile_sources" ADD CONSTRAINT "jules_profile_sources_profile_id_jules_profiles_id_fk" FOREIGN KEY ("profile_id") REFERENCES "jules_profiles"("id") ON DELETE cascade;
ALTER TABLE "jules_profile_sources" ADD CONSTRAINT "jules_profile_sources_company_source_id_company_jules_sources_id_fk" FOREIGN KEY ("company_source_id") REFERENCES "company_jules_sources"("id") ON DELETE cascade;
ALTER TABLE "jules_sessions" ADD CONSTRAINT "jules_sessions_company_id_companies_id_fk" FOREIGN KEY ("company_id") REFERENCES "companies"("id") ON DELETE cascade;
ALTER TABLE "jules_sessions" ADD CONSTRAINT "jules_sessions_profile_id_jules_profiles_id_fk" FOREIGN KEY ("profile_id") REFERENCES "jules_profiles"("id");
ALTER TABLE "jules_sessions" ADD CONSTRAINT "jules_sessions_company_source_id_company_jules_sources_id_fk" FOREIGN KEY ("company_source_id") REFERENCES "company_jules_sources"("id");
ALTER TABLE "jules_sessions" ADD CONSTRAINT "jules_sessions_paperclip_run_id_heartbeat_runs_id_fk" FOREIGN KEY ("paperclip_run_id") REFERENCES "heartbeat_runs"("id") ON DELETE cascade;
ALTER TABLE "jules_capacity_events" ADD CONSTRAINT "jules_capacity_events_profile_id_jules_profiles_id_fk" FOREIGN KEY ("profile_id") REFERENCES "jules_profiles"("id") ON DELETE cascade;
ALTER TABLE "jules_capacity_events" ADD CONSTRAINT "jules_capacity_events_company_id_companies_id_fk" FOREIGN KEY ("company_id") REFERENCES "companies"("id") ON DELETE cascade;
ALTER TABLE "jules_capacity_events" ADD CONSTRAINT "jules_capacity_events_session_id_jules_sessions_id_fk" FOREIGN KEY ("session_id") REFERENCES "jules_sessions"("id") ON DELETE set null;
ALTER TABLE "jules_callback_events" ADD CONSTRAINT "jules_callback_events_company_id_companies_id_fk" FOREIGN KEY ("company_id") REFERENCES "companies"("id") ON DELETE cascade;
ALTER TABLE "jules_callback_events" ADD CONSTRAINT "jules_callback_events_session_id_jules_sessions_id_fk" FOREIGN KEY ("session_id") REFERENCES "jules_sessions"("id") ON DELETE cascade;
CREATE UNIQUE INDEX "company_jules_sources_company_repo_uniq" ON "company_jules_sources" ("company_id", "repository");
CREATE UNIQUE INDEX "jules_profile_sources_profile_source_uniq" ON "jules_profile_sources" ("profile_id", "company_source_id");
